@@ -967,6 +967,13 @@ static bool zswap_decompress(struct zswap_entry *entry, struct folio *folio)
 		sg_set_folio(&output, folio, PAGE_SIZE, 0);
 		acomp_request_set_params(acomp_ctx->req, input, &output,
 					 entry->length, PAGE_SIZE);
+		/* Contiguous input lets synchronous codecs avoid stream walks. */
+		if (!acomp_is_async(acomp_ctx->acomp) && !sg_is_last(input)) {
+			memcpy_from_sglist(acomp_ctx->buffer, input, 0,
