+						    acomp_ctx->buffer, entry->length);
+		}
 		ret = crypto_acomp_decompress(acomp_ctx->req);
 		ret = crypto_wait_req(ret, &acomp_ctx->wait);
 		dlen = acomp_ctx->req->dlen;

